"""person_detector 노드.

RealSense D435 컬러 프레임에서 YOLO 로 사람을 감지하고,
사람이 임계 거리(distance_threshold) 보다 가까이 들어오면 ROS2 토픽을 발행한다.

발행 토픽:
  /person_detector/event    (std_msgs/String, JSON)  - 감지 이벤트 상세
  /person_detector/detected (std_msgs/Bool)          - 임계 거리 안에 사람이 있으면 True

엣지 트리거 + 쿨다운으로, 사람이 임계 거리 안으로 새로 들어온 순간에만 이벤트를 발행한다.
(매 프레임 스팸 발행 방지)
"""

import json
import time

import cv2
import numpy as np
import rclpy
from rclpy.node import Node
from std_msgs.msg import Bool, String

from person_detector.realsense_camera import RealSenseCamera, WebcamCamera
from person_detector.pose_analysis import estimate_facing, detect_handshake_ready
from person_detector.stream_server import MjpegServer

WINDOW_NAME = 'person_detector'


class PersonDetectorNode(Node):
    def __init__(self):
        super().__init__('person_detector')

        # ---- 파라미터 선언 ----
        self.declare_parameter('distance_threshold', 3.0)   # 임계 거리(m): 이보다 가까우면 발행
        # 거리 게이트 무시(웹캠처럼 거리 추정이 부정확할 때). 웹캠이면 자동 True
        self.declare_parameter('ignore_distance', False)
        self.declare_parameter('min_confidence', 0.5)       # YOLO 사람 신뢰도 임계값
        # pose 모델: bbox(거리용) + 17개 키포인트(방향/악수 추정용) 동시 제공
        self.declare_parameter('yolo_model', 'yolov8n-pose.pt')
        self.declare_parameter('keypoint_conf', 0.3)        # 키포인트 유효 신뢰도 임계값
        self.declare_parameter('camera_type', 'realsense')  # 'realsense' | 'webcam' | 'ros'
        self.declare_parameter('webcam_index', 0)           # 웹캠 /dev/videoN 인덱스
        # ros 모드(realsense2_camera 토픽 구독)용 토픽 이름
        self.declare_parameter('color_topic',
                               '/camera/camera/color/image_raw')
        self.declare_parameter('depth_topic',
                               '/camera/camera/aligned_depth_to_color/image_raw')
        self.declare_parameter('person_height_m', 1.7)      # 웹캠 거리추정용 평균 키(m)
        self.declare_parameter('focal_px', 600.0)           # 웹캠 거리추정용 초점거리(px)
        self.declare_parameter('width', 640)
        self.declare_parameter('height', 480)
        self.declare_parameter('fps', 30)
        # facing=true 판정: 정면(front)을 이 시간 이상 유지(머무름)해야 대화 의도로 간주
        self.declare_parameter('facing_dwell_sec', 3.0)
        # handshaking=true 판정: 악수 자세를 이 시간 이상 유지
        self.declare_parameter('handshake_dwell_sec', 2.0)
        # 토픽 발행 간격(초): 감지는 매 프레임, 발행만 이 주기로
        self.declare_parameter('publish_interval_sec', 5.0)
        self.declare_parameter('event_topic', '/person_detector/event')
        self.declare_parameter('detected_topic', '/person_detector/detected')
        self.declare_parameter('enable_display', True)      # OpenCV 창 표시(로컬 GUI)
        self.declare_parameter('enable_stream', False)      # MJPEG 웹 스트리밍(컨테이너용)
        self.declare_parameter('stream_port', 8080)

        self.distance_threshold = self.get_parameter('distance_threshold').value
        self.min_confidence = self.get_parameter('min_confidence').value
        self.yolo_model_name = self.get_parameter('yolo_model').value
        self.keypoint_conf = self.get_parameter('keypoint_conf').value
        self.camera_type = self.get_parameter('camera_type').value
        # 웹캠은 거리 추정이 부정확 -> 거리 게이트 자동 무시
        self.ignore_distance = (self.get_parameter('ignore_distance').value
                                or self.camera_type == 'webcam')
        self.webcam_index = self.get_parameter('webcam_index').value
        self.color_topic = self.get_parameter('color_topic').value
        self.depth_topic = self.get_parameter('depth_topic').value
        self.person_height_m = self.get_parameter('person_height_m').value
        self.focal_px = self.get_parameter('focal_px').value
        self.width = self.get_parameter('width').value
        self.height = self.get_parameter('height').value
        self.fps = self.get_parameter('fps').value
        self.facing_dwell_sec = self.get_parameter('facing_dwell_sec').value
        self.handshake_dwell_sec = self.get_parameter('handshake_dwell_sec').value
        self.publish_interval_sec = self.get_parameter('publish_interval_sec').value
        self.enable_display = self.get_parameter('enable_display').value
        self.enable_stream = self.get_parameter('enable_stream').value
        self.stream_port = self.get_parameter('stream_port').value

        event_topic = self.get_parameter('event_topic').value
        detected_topic = self.get_parameter('detected_topic').value

        # ---- 퍼블리셔 ----
        self.event_pub = self.create_publisher(String, event_topic, 10)
        self.detected_pub = self.create_publisher(Bool, detected_topic, 10)

        # ---- 상태 (dwell 타이머) ----
        self._front_since = None       # 임계거리 안에서 정면을 보기 시작한 시각 (없으면 None)
        self._handshake_since = None   # 악수 자세가 시작된 시각 (없으면 None)
        self._pose_since = 0.0         # 현재 pose 카테고리가 유지되기 시작한 시각
        self._last_pose = None         # 직전 프레임 pose 카테고리
        self._last_publish = 0.0       # 마지막 토픽 발행 시각

        # ---- 모델 / 카메라 초기화 ----
        # ultralytics / torch 는 무겁고 rosdep 외부 의존성이라 여기서 지연 import
        import torch
        from ultralytics import YOLO

        self.use_gpu = torch.cuda.is_available()
        self.device = 0 if self.use_gpu else 'cpu'   # ultralytics device 인자
        # FP16(half)은 약한 GPU 에서 pose 키포인트 신뢰도를 떨어뜨려 방향 추정이 깨질 수
        # 있으므로 기본 비활성(FP32). 파라미터로 강제 가능.
        self.declare_parameter('use_half', False)
        self.use_half = self.use_gpu and self.get_parameter('use_half').value
        gpu_name = torch.cuda.get_device_name(0) if self.use_gpu else 'CPU'

        self.get_logger().info(
            f'person_detector 시작: 임계거리<={self.distance_threshold}m, '
            f'conf>={self.min_confidence}, model={self.yolo_model_name}, '
            f'device={gpu_name}(half={self.use_half})'
        )

        self.yolo = YOLO(self.yolo_model_name)
        self.yolo.to('cuda' if self.use_gpu else 'cpu')

        if self.camera_type == 'webcam':
            self.camera = WebcamCamera(self.webcam_index, self.width, self.height)
            self.depth_scale = self.camera.start()
            self.get_logger().info(
                f'웹캠 시작 완료(index={self.webcam_index}). '
                f'depth 없음 -> bbox 높이로 거리 근사 '
                f'(person_height={self.person_height_m}m, focal={self.focal_px}px)'
            )
        elif self.camera_type == 'ros':
            from person_detector.ros_camera import RosTopicCamera
            self.camera = RosTopicCamera(self, self.color_topic, self.depth_topic)
            self.depth_scale = 0.001  # depth 토픽 16UC1(mm) -> m
            self.camera.start()
            self.get_logger().info('ROS 토픽 구독 모드 시작')
        else:
            self.camera = RealSenseCamera(self.width, self.height, self.fps)
            self.depth_scale = self.camera.start()
            self.get_logger().info(
                f'RealSense 시작 완료. depth_scale={self.depth_scale}'
            )

        # MJPEG 웹 스트리밍 (GUI 없는 컨테이너용)
        self.stream = None
        if self.enable_stream:
            self.stream = MjpegServer(self.stream_port)
            self.stream.start()
            self.get_logger().info(
                f'웹 스트리밍 시작: http://<host>:{self.stream_port}/')

        # FPS 측정용
        self._fps_t0 = time.time()
        self._fps_count = 0

    # ----------------------------------------------------------------
    def estimate_distance_depth(self, depth_image, x1, y1, x2, y2):
        """RealSense: bbox 중심 주변 패치의 유효 depth 중앙값(m). 없으면 None."""
        cx = int((x1 + x2) / 2)
        cy = int((y1 + y2) / 2)
        h, w = depth_image.shape[:2]
        if not (0 <= cx < w and 0 <= cy < h):
            return None

        # 중심 주변 11x11 패치에서 0(무효)이 아닌 값만 사용
        half = 5
        x_lo, x_hi = max(0, cx - half), min(w, cx + half + 1)
        y_lo, y_hi = max(0, cy - half), min(h, cy + half + 1)
        patch = depth_image[y_lo:y_hi, x_lo:x_hi].astype(np.float32)
        valid = patch[patch > 0]
        if valid.size == 0:
            return None
        return float(np.median(valid)) * self.depth_scale

    def estimate_distance_bbox(self, y1, y2):
        """웹캠(depth 없음): bbox 높이로 거리 근사.

        핀홀 모델: distance = person_height_m * focal_px / bbox_height_px
        (사람이 가까울수록 bbox 높이가 커져 거리가 작아진다)
        YOLO 가 전신을 못 잡으면(다리 잘림 등) 오차가 커지므로 어디까지나 근사값.
        """
        bbox_h = max(1.0, y2 - y1)
        return self.person_height_m * self.focal_px / bbox_h

    def detect_persons(self, color_image, depth_image):
        """감지된 모든 사람 목록을 반환. 각 항목: {distance, conf, bbox, near}.

        near = 임계 거리보다 가까운가. distance 가 None(유효 depth 없음)이면 False.
        """
        results = self.yolo(
            color_image, classes=[0], device=self.device,
            half=self.use_half, verbose=False,
        )
        if isinstance(results, list):
            results = results[0]

        # pose 모델이면 키포인트 배열 (N,17,3) 확보 (detect 모델이면 None)
        kpts_all = None
        if getattr(results, 'keypoints', None) is not None:
            kpts_all = results.keypoints.data.cpu().numpy()

        persons = []
        for i, box in enumerate(results.boxes):
            if int(box.cls[0]) != 0:  # person 만
                continue
            conf = float(box.conf[0])
            if conf < self.min_confidence:
                continue
            x1, y1, x2, y2 = box.xyxy[0].tolist()
            if depth_image is not None:
                distance = self.estimate_distance_depth(depth_image, x1, y1, x2, y2)
            else:
                distance = self.estimate_distance_bbox(y1, y2)
            near = distance is not None and distance <= self.distance_threshold

            # 방향 / 악수 자세 (pose 키포인트 있을 때만)
            facing, handshake_ready, kp = 'unknown', False, None
            if kpts_all is not None and i < len(kpts_all):
                kp = kpts_all[i]
                facing = estimate_facing(kp, (x1, y1, x2, y2), self.keypoint_conf)
                handshake_ready = detect_handshake_ready(kp, self.keypoint_conf)

            persons.append({
                'distance': round(distance, 3) if distance is not None else None,
                'conf': round(conf, 3),
                'bbox': [round(x1, 1), round(y1, 1), round(x2, 1), round(y2, 1)],
                'near': near,
                'facing': facing,
                'handshake_ready': handshake_ready,
                '_kp': kp,   # 렌더용(내부), JSON 발행에는 제외
            })
        return persons

    def run(self):
        """메인 처리 루프: 캡처 -> 추론 -> 발행 -> 렌더.

        ROS timer/executor 를 쓰지 않고 직접 루프를 돌려, GUI(cv2) 가 메인 스레드에서
        끊김 없이 동작하고 프레임 처리가 밀리지 않도록 한다.
        퍼블리셔는 spin 없이도 publish 가능하다.
        """
        while rclpy.ok():
            if not self.process_once():
                break

    def process_once(self):
        """한 프레임 처리. 계속 진행하면 True, 종료하려면 False 반환."""
        try:
            color_image, depth_image = self.camera.read()
        except Exception as e:  # pragma: no cover - 하드웨어 의존
            self.get_logger().warn(f'카메라 read 실패: {e}')
            return True
        # depth_image 는 웹캠 모드에서 항상 None 이므로 color 만 확인한다.
        if color_image is None:
            return True

        persons = self.detect_persons(color_image, depth_image)
        now = time.time()

        # 가장 가까운 사람 (거리 유효한 것 중 최소). 거리 None 은 제외.
        with_dist = [p for p in persons if p['distance'] is not None]
        nearest = min(with_dist, key=lambda p: p['distance']) if with_dist else None
        distance = nearest['distance'] if nearest else None

        # 가장 가까운 사람의 현재 포즈(방향): front/back/left/right/unknown
        pose = nearest['facing'] if nearest else None

        # 같은 pose 카테고리를 유지한 시간 추적
        if pose is not None and pose == self._last_pose:
            pass
        else:
            self._pose_since = now
            self._last_pose = pose
        pose_held_sec = round(now - self._pose_since, 1) if pose is not None else 0.0

        # facing: 1순위 거리(임계 안) -> 2순위 정면(front) -> 3초 이상 유지
        # ignore_distance 면 거리 조건 통과(사람만 있으면 됨)
        in_range = nearest is not None and (
            self.ignore_distance or distance <= self.distance_threshold)
        raw_front = in_range and pose == 'front'
        self._front_since = self._front_since or now if raw_front else None
        facing = raw_front and (now - self._front_since) >= self.facing_dwell_sec

        # handshaking: facing=true 일 때만 가능. facing=false 이면 무조건 false
        raw_handshake = facing and nearest['handshake_ready']
        self._handshake_since = self._handshake_since or now if raw_handshake else None
        handshaking = (raw_handshake
                       and (now - self._handshake_since) >= self.handshake_dwell_sec)

        # ---- 발행은 publish_interval_sec 주기로 (감지/dwell 은 매 프레임) ----
        if (now - self._last_publish) >= self.publish_interval_sec:
            self.publish_status(distance, pose, pose_held_sec, facing, handshaking)
            self.detected_pub.publish(Bool(data=in_range))
            self._last_publish = now
            # 진단 로그: 최근접 사람 키포인트 신뢰도 + 판정
            if nearest is not None and nearest.get('_kp') is not None:
                k = nearest['_kp']
                self.get_logger().info(
                    f"[pose] {pose} dist={distance} facing={facing} "
                    f"hs_raw={nearest['handshake_ready']} handshaking={handshaking} | "
                    f"nose={k[0][2]:.2f} Lsh={k[5][2]:.2f} Rsh={k[6][2]:.2f}"
                )

        # FPS 측정 (5초마다 로그)
        self._fps_count += 1
        elapsed = now - self._fps_t0
        if elapsed >= 5.0:
            self.get_logger().info(f'처리 속도: {self._fps_count / elapsed:.1f} FPS')
            self._fps_t0 = now
            self._fps_count = 0

        if self.enable_display or self.enable_stream:
            return self.render(color_image, persons, distance, pose,
                               pose_held_sec, facing, handshaking)
        return True

    def publish_status(self, distance, pose, pose_held_sec, facing, handshaking):
        """상태 발행: 거리 + 현재 포즈(방향/유지시간) + facing/handshaking 불리언."""
        payload = {
            'distance': distance,            # 가장 가까운 사람까지 거리(m), 없으면 null
            'pose': pose,                    # 현재 방향: front/back/left/right/unknown, 없으면 null
            'pose_held_sec': pose_held_sec,  # 현재 pose 를 유지한 시간(초)
            'facing': facing,                # 임계거리 안 + 정면 + dwell = 대화 의도
            'handshaking': handshaking,      # 악수하려는 자세
            'stamp': self.get_clock().now().nanoseconds,
        }
        msg = String()
        msg.data = json.dumps(payload)
        self.event_pub.publish(msg)

    def render(self, color_image, persons, distance, pose, pose_held_sec, facing, handshaking):
        """감지 결과를 OpenCV 창에 그린다.

        - 임계 거리 안 사람: 초록 굵은 박스 / 그 외: 빨강 얇은 박스
        - 상단에 발행 값(distance/pose/facing/handshaking)
        - 앱이 취할 액션을 큰 배너로 표시 (handshaking > facing 우선)
        """
        for p in persons:
            x1, y1, x2, y2 = [int(v) for v in p['bbox']]
            if p['near']:
                color, thickness = (0, 255, 0), 3
            else:
                color, thickness = (0, 0, 255), 2
            cv2.rectangle(color_image, (x1, y1), (x2, y2), color, thickness)

            # 키포인트 점 표시
            if p.get('_kp') is not None:
                for (kx, ky, kc) in p['_kp']:
                    if kc >= self.keypoint_conf:
                        cv2.circle(color_image, (int(kx), int(ky)), 3, (255, 255, 0), -1)

            dist_txt = f"{p['distance']:.2f}m" if p['distance'] is not None else 'no depth'
            label = f"{dist_txt} dir:{p['facing']}"
            cv2.putText(color_image, label, (x1, max(0, y1 - 8)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.6, color, 2)

        # 상단: 실제 발행되는 값
        dist_str = f"{distance:.2f}m" if distance is not None else "none"
        cv2.putText(color_image, f"distance: {dist_str}   pose: {pose} ({pose_held_sec}s)", (10, 25),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 255, 255), 2)
        cv2.putText(color_image, f"facing: {facing}", (10, 52),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.7,
                    (0, 255, 0) if facing else (200, 200, 200), 2)
        cv2.putText(color_image, f"handshaking: {handshaking}", (10, 79),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.7,
                    (0, 165, 255) if handshaking else (200, 200, 200), 2)

        # 앱이 취할 액션 배너 (handshaking 우선)
        if handshaking:
            action, action_color = 'ACTION: HANDSHAKE', (0, 165, 255)
        elif facing:
            action, action_color = 'ACTION: TALK', (0, 255, 0)
        else:
            action, action_color = 'ACTION: -', (150, 150, 150)
        h, w = color_image.shape[:2]
        (tw, th), _ = cv2.getTextSize(action, cv2.FONT_HERSHEY_SIMPLEX, 1.0, 3)
        x = (w - tw) // 2
        y = h - 25
        cv2.rectangle(color_image, (x - 12, y - th - 14), (x + tw + 12, y + 12),
                      (0, 0, 0), -1)
        cv2.putText(color_image, action, (x, y),
                    cv2.FONT_HERSHEY_SIMPLEX, 1.0, action_color, 3)

        # 웹 스트리밍: 그린 프레임을 JPEG 로 인코딩해 푸시
        if self.stream is not None:
            ok, jpeg = cv2.imencode('.jpg', color_image,
                                    [int(cv2.IMWRITE_JPEG_QUALITY), 70])
            if ok:
                self.stream.update(jpeg.tobytes())

        # 로컬 GUI 창 (있을 때만)
        if self.enable_display:
            cv2.imshow(WINDOW_NAME, color_image)
            if (cv2.waitKey(1) & 0xFF) == ord('q'):
                self.get_logger().info("'q' 입력 -> 종료")
                return False
        return True

    def destroy_node(self):
        try:
            self.camera.stop()
        except Exception:
            pass
        if self.stream is not None:
            try:
                self.stream.stop()
            except Exception:
                pass
        if self.enable_display:
            try:
                cv2.destroyAllWindows()
            except Exception:
                pass
        super().destroy_node()


def main(args=None):
    rclpy.init(args=args)
    node = PersonDetectorNode()
    try:
        node.run()
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
